-- =====================================================================
-- Fiches « Que fait l'entreprise ? »
--
-- Fichier GÉNÉRÉ par tools/build_fiches.py — ne pas éditer à la main.
-- Source : premier paragraphe de l'article Wikipédia de chaque société,
-- condensé en deux phrases par langue. Aucun fait n'est ajouté à ce que
-- l'article dit.
--
-- Les fiches rédigées à la main ne sont pas écrasées.
-- =====================================================================

update public.securities s set
  description_fr = v.fr,
  description_en = v.en
from (values
  ('0300', 'Midea Group fabrique des appareils électroménagers : micro-ondes, climatiseurs, réfrigérateurs, machines à laver, petits électroménagers de cuisine et systèmes de chauffage-ventilation. Le groupe a déclaré un chiffre d''affaires de 40,5 milliards de dollars en 2020 et emploie environ 150 000 personnes.', 'Midea Group manufactures electrical appliances: microwaves, air conditioning systems, refrigerators, washing machines, small kitchen appliances, and heating and ventilation systems. The group reported sales revenue of US$40.5 billion in 2020 and employs approximately 150,000 people.'),
  ('0941', 'China Mobile fournit des services de téléphonie mobile et multimédia à travers un réseau de télécommunications couvrant la Chine continentale et Hong Kong. Avec 945,50 millions d''abonnés en juin 2021, c''est le plus grand opérateur de réseau mobile au monde.', 'China Mobile provides mobile voice and multimedia services through a telecommunications network covering mainland China and Hong Kong. With 945.50 million subscribers as of June 2021, it is the world''s largest mobile network operator by number of subscribers.'),
  ('1093', 'CSPC Pharmaceutical Group fabrique et vend des médicaments et des principes actifs pharmaceutiques. L''entreprise, basée dans la province du Hebei en Chine, compte environ 15 000 salariés répartis dans plus de dix filiales.', 'CSPC Pharmaceutical Group manufactures and sells pharmaceutical products and active pharmaceutical ingredients. The company, based in Hebei Province in China, employs around 15,000 people across more than ten subsidiaries.'),
  ('1099', 'Sinopharm Group est une entreprise pharmaceutique chinoise. Elle est cotée à la Bourse de Hong Kong depuis 2009, où elle a été introduite à 16 dollars de Hong Kong par action.', 'Sinopharm Group is a Chinese pharmaceutical company. It has been listed on the Hong Kong Stock Exchange since 2009, when it was introduced at HK$16 per share.'),
  ('1929', 'Chow Tai Fook est un conglomérat hongkongais diversifié qui opère dans la joaillerie, l''immobilier, l''hôtellerie, les grands magasins, les transports, l''énergie et les télécommunications. Le groupe est en partie coté en bourse par ses filiales Chow Tai Fook Jewellery Group Limited et New World Development, cette dernière affichant une capitalisation boursière de 105,7 milliards HK$ au 31 décembre 2018.', 'Chow Tai Fook is a Hong Kong-based diversified conglomerate operating in jewellery, property development, hotels, department stores, transportation, energy, and telecommunications. The group is partially listed on the stock market through its subsidiaries Chow Tai Fook Jewellery Group Limited and New World Development, the latter with a market capitalisation of HK$105.7 billion as of 31 December 2018.'),
  ('2318', 'Ping An Insurance est un groupe financier chinois fondé en 1988 qui propose des services d''assurance, de banque, de gestion d''actifs et de services financiers. Le groupe figure parmi les 50 plus grandes entreprises de la Bourse de Shanghai et fait partie de l''indice Hang Seng de la Bourse de Hong Kong.', 'Ping An Insurance is a Chinese financial services holding company founded in 1988 that provides insurance, banking, asset management and financial services. The group ranks among the top 50 companies on the Shanghai Stock Exchange and is a constituent of the Hang Seng Index on the Hong Kong Stock Exchange.'),
  ('3988', 'La Bank of China est une banque chinoise d''État qui propose des services financiers et bancaires. Selon les données de 2019, elle était le deuxième plus grand prêteur en Chine et le neuvième plus grand établissement bancaire du monde en capitalisation boursière.', 'The Bank of China is a state-owned Chinese bank that provides banking and financial services. As of 2019, it was the second-largest lender in China and the ninth-largest bank in the world by market capitalization.'),
  ('A', 'Agilent Technologies fabrique et vend des instruments, des logiciels, des services et des consommables destinés aux laboratoires. L''entreprise, créée en 1999 comme filiale de Hewlett-Packard, intervient sur les marchés pharmaceutiques, diagnostiques, cliniques et de la recherche académique et gouvernementale.', 'Agilent Technologies manufactures and sells instruments, software, services, and consumables for laboratories. Founded in 1999 as a spin-off from Hewlett-Packard, the company operates in pharmaceutical, diagnostics, clinical, and academic and government research markets.'),
  ('ALL', 'Allstate est une compagnie d''assurance américaine fondée en 1931. Elle propose des assurances aux particuliers aux États-Unis et au Canada.', 'Allstate is an American insurance company founded in 1931. It provides personal line insurance to individuals in the United States and Canada.'),
  ('ASSA-B', 'Assa Abloy vend des produits et services liés aux serrures, portes, portails et systèmes d''automatisation d''accès. L''entreprise propose également des solutions de contrôle d''accès et d''identification utilisant des clés, cartes, badges, appareils mobiles et systèmes biométriques.', 'Assa Abloy sells products and services related to locks, doors, gates, and entrance automation systems. The company also provides access control and identity verification solutions using keys, cards, tags, mobile devices, and biometric systems.'),
  ('BA', 'Boeing conçoit et fabrique des avions, des hélicoptères, des fusées, des satellites et des missiles pour des clients dans le monde entier. L''entreprise propose aussi des services de location et de support produit.', 'Boeing designs and manufactures airplanes, rotorcraft, rockets, satellites, and missiles for customers worldwide. The company also provides leasing and product support services.'),
  ('BB', 'Bic est une entreprise française fondée en 1945 qui fabrique et vend des stylos, articles de papeterie, rasoirs, briquets et matériel sportif. La famille Bich en contrôle plus de 45 % du capital.', 'Bic is a French company founded in 1945 that manufactures and sells pens, stationery items, razors, lighters and sports equipment. The Bich family controls over 45% of the company''s capital.'),
  ('BCE', 'BCE Inc. est un groupe canadien fondé en 1983 qui exploite Bell Canada, un fournisseur de télécommunications et de services médias. Le groupe figure parmi les plus grandes entreprises du Canada.', 'BCE Inc. is a Canadian company founded in 1983 that operates Bell Canada, a telecommunications and media services provider. The group ranks among Canada''s largest corporations.'),
  ('BILI', 'Bilibili est une plateforme chinoise de partage de vidéos fondée en 2010, spécialisée dans les contenus liés aux anime, mangas et jeux vidéo, qui propose aussi de la musique, de la danse, de la science et du divertissement. Elle permet aux utilisateurs de visionner des vidéos, d''ajouter des commentaires interactifs et d''accéder à des services de diffusion en direct et de jeux mobiles.', 'Bilibili is a Chinese video-sharing platform founded in 2010, specializing in anime, manga and video game content, which also offers music, dance, science and entertainment videos. It allows users to watch videos, add interactive comments and access live streaming and mobile gaming services.'),
  ('BNZL', 'Bunzl est une entreprise britannique de distribution et d''externalisation de services, cotée à la Bourse de Londres depuis 1957 et membre de l''indice FTSE 100. Elle s''est recentrée sur la distribution après avoir divesti ses activités de production entre les années 1990 et 2005.', 'Bunzl is a British multinational distribution and outsourcing company listed on the London Stock Exchange since 1957 and a constituent of the FTSE 100 Index. It restructured to focus purely on distribution, divesting its manufacturing operations from the early 1990s through 2005.'),
  ('BOL', 'Bolloré est un groupe français fondé en 1822 qui opère dans la logistique, l''énergie, l''automobile et les médias. En 2021, il réalise plus de 16 milliards d''euros de chiffre d''affaires et emploie 73 000 personnes dans le monde.', 'Bolloré is a French group founded in 1822 operating in logistics, energy, automobiles and media. In 2021, it generated over 16 billion euros in revenue and employed 73,000 people worldwide.'),
  ('CB', 'Chubb Limited est une compagnie d''assurance qui vend des contrats d''assurance dommages, accidents, santé, réassurance et vie à des entreprises multinationales, des petites entreprises, des particuliers et d''autres assureurs. Elle opère dans 55 pays et territoires et emploie environ 31 000 personnes.', 'Chubb Limited is an insurance company that sells property and casualty, accident, health, reinsurance and life insurance contracts to multinational corporations, small businesses, individuals and other insurers. It operates in 55 countries and territories and employs approximately 31,000 people.'),
  ('CCO', 'Cameco Corporation produit et vend de l''uranium, utilisé notamment pour la production d''électricité. L''entreprise, basée au Canada, est le plus grand producteur d''uranium coté en bourse au monde.', 'Cameco Corporation produces and sells uranium, which is used notably for electricity generation. The company, based in Canada, is the world''s largest publicly traded uranium producer.'),
  ('CFR', 'Richemont est un groupe suisse fondé en 1988 qui produit et vend des biens de luxe : bijoux, montres, maroquinerie, stylos, vêtements et accessoires. Le groupe possède plus de trente marques prestigieuses comme Cartier, Van Cleef & Arpels, Montblanc et IWC, et figure parmi les quatre plus grandes entreprises de l''indice boursier suisse.', 'Richemont is a Swiss group founded in 1988 that produces and sells luxury goods: jewellery, watches, leather goods, pens, clothing and accessories. The group owns more than thirty prestigious brands such as Cartier, Van Cleef & Arpels, Montblanc and IWC, and ranks among the four largest companies in the Swiss stock market index.'),
  ('COL', 'Inmobiliaria Colonial est une entreprise immobilière espagnole qui loue des biens, achète et vend des terres, et développe des immeubles. Le groupe opère comme une structure de placement immobilier (REIT).', 'Inmobiliaria Colonial is a Spanish real estate company that rents properties, buys and sells land, and develops buildings. The group operates as a real estate investment trust (REIT).'),
  ('CSU', 'Constellation Software achète et conserve des sociétés de logiciels spécialisés, c''est-à-dire des éditeurs qui servent une niche industrielle précise. Depuis sa création en 1995, l''entreprise a acquis plus de 850 entreprises dans plus de 100 secteurs différents à travers le monde.', 'Constellation Software acquires and owns vertical market software companies, which are software firms serving a specific industry niche. Since its founding in 1995, the company has acquired over 850 businesses across more than 100 industry verticals worldwide.'),
  ('CTAS', 'Cintas vend des uniformes, des produits de nettoyage et d''hygiène, ainsi que des équipements de sécurité et d''incendie aux entreprises. L''entreprise, basée en Ohio, compte 44 500 salariés et a généré 7,09 milliards de dollars de chiffre d''affaires en 2020.', 'Cintas sells uniforms, cleaning and restroom supplies, and safety and fire protection equipment to businesses. The company, headquartered in Ohio, employed 44,500 people in 2023 and reported $7.09 billion in revenue in 2020.'),
  ('CVNA', 'Carvana est une entreprise américaine qui vend des voitures en ligne. Elle figure parmi les plus jeunes entreprises à avoir intégré la liste Fortune 500 en 2021.', 'Carvana is an American company that sells cars online. It was named to the Fortune 500 list in 2021, making it one of the youngest companies to achieve this ranking.'),
  ('DGX', 'Quest Diagnostics propose des services de diagnostic médical : tests de dépistage du cancer, des maladies cardiovasculaires, des maladies infectieuses, des troubles neurologiques et du COVID-19, ainsi que des tests de dépistage de drogue ordonnés par les tribunaux ou les employeurs. L''entreprise opère aux États-Unis, à Porto Rico, au Mexique et au Brésil, compte environ 48 000 salariés et a généré plus de 7,7 milliards de dollars de chiffre d''affaires en 2019.', 'Quest Diagnostics provides clinical laboratory and diagnostic testing services, including tests for cancer, cardiovascular disease, infectious disease, neurological disorders, COVID-19, and drug testing for employment and legal purposes. The company operates in the United States, Puerto Rico, Mexico, and Brazil, employs approximately 48,000 people, and generated more than $7.7 billion in revenue in 2019.'),
  ('DHL', 'Deutsche Post assure le service de courrier traditionnel en Allemagne sous la marque du groupe DHL. L''entreprise est l''héritière du monopole d''État allemand sur la poste, dont l''exclusivité a pris fin en 2008.', 'Deutsche Post provides domestic mail services in Germany under the DHL Group brand. The company is the successor to the former state-owned German postal monopoly, which lost its exclusive status in 2008.'),
  ('FFH', 'Fairfax Financial Holdings est un groupe financier canadien fondé en 1985 qui assure les risques (assurance et réassurance dommages) à travers 26 sociétés décentralisées et gère un portefeuille d''investissement de plus de 70 milliards de dollars. Le groupe opère aussi dans les services à la consommation, la vente au détail, la logistique, l''agriculture et la banque en Amérique du Nord, Europe et Asie.', 'Fairfax Financial Holdings is a Canadian financial holding company founded in 1985 that provides property and casualty insurance and reinsurance through 26 decentralized companies and manages an investment portfolio exceeding US$70 billion. The group also operates in consumer services, retail, logistics, agriculture, and banking across North America, Europe, and Asia.'),
  ('FICO', 'Fair Isaac propose des services d''analyse de données, notamment des scores de crédit (les scores FICO) qui évaluent le risque de crédit des consommateurs. En 2020, l''entreprise a généré un chiffre d''affaires de 1,29 milliard de dollars.', 'Fair Isaac provides data analytics services, particularly credit scoring services (FICO scores) that assess consumer credit risk. In 2020, the company generated revenue of $1.29 billion.'),
  ('FTS', 'Fortis Inc. est une holding qui possède des sociétés de distribution et de transmission d''électricité. Elle opère au Canada, aux États-Unis, en Amérique centrale et aux Caraïbes.', 'Fortis Inc. is a holding company that owns electric utility companies for distribution and transmission. It operates in Canada, the United States, Central America and the Caribbean.'),
  ('GLEN', 'Glencore extrait et commercialise des matières premières : métaux, minéraux, pétrole, charbon, gaz naturel et produits agricoles. L''entreprise approvisionne des secteurs comme l''automobile, la production d''acier et l''énergie dans le monde entier.', 'Glencore extracts and trades commodities: metals, minerals, crude oil, coal, natural gas and agricultural products. The company supplies industries such as automotive, steel production and power generation worldwide.'),
  ('GTT', 'GTT fabrique des systèmes de confinement pour stocker et transporter le gaz naturel liquéfié à bord de navires. L''entreprise vend ses équipements aux chantiers navals, principalement en Asie du Sud-Est.', 'GTT manufactures confinement systems for storing and transporting liquefied natural gas aboard ships. The company sells its equipment to shipyards, mainly in Southeast Asia.'),
  ('HEIA', 'Heineken produit et vend de la bière et du cidre dans plus de 70 pays. En 2019, l''entreprise génère 23,9 milliards d''euros de chiffre d''affaires annuel et emploie environ 85 000 personnes.', 'Heineken produces and sells beer and cider in more than 70 countries. In 2019, the company generates 23.9 billion euros in annual revenue and employs approximately 85,000 people.'),
  ('HMC', 'Honda fabrique des automobiles, des motocyclettes, des scooters, des quads, des avions d''affaires, des générateurs électriques, des moteurs de bateaux et des équipements de jardinage et de bricolage. En 2008, l''entreprise a vendu plus de dix-sept millions de moteurs à quatre temps, ce qui en a fait le plus important producteur du monde.', 'Honda manufactures automobiles, motorcycles, scooters, quads, business aircraft, electric generators, boat engines, and gardening and DIY equipment. In 2008, the company sold more than seventeen million four-stroke engines, making it the world''s largest producer.'),
  ('HPE', 'HPE vend des serveurs, du stockage informatique, des équipements réseau, des logiciels de conteneurisation et des services de conseil aux entreprises. Fondée en 2015 lors du scission de Hewlett-Packard, elle était classée 107e entreprise américaine par chiffre d''affaires en 2018.', 'HPE sells servers, storage systems, networking equipment, containerization software and consulting services to businesses. Founded in 2015 as a spin-off from Hewlett-Packard, it ranked 107th among US corporations by revenue in 2018.'),
  ('ITUB', 'Itaú Unibanco est un groupe financier brésilien créé en 2008 de la fusion entre Banco Itaú et Unibanco. Le groupe propose des services bancaires et financiers.', 'Itaú Unibanco is a Brazilian financial group created in 2008 from the merger of Banco Itaú and Unibanco. The group offers banking and financial services.'),
  ('IX', 'Orix est un groupe de services financiers basé à Tokyo, fondé en 1964. L''extrait ne précise pas ses activités ni son ordre de grandeur.', 'Orix is a financial services group based in Tokyo, founded in 1964. The excerpt does not specify its activities or scale.'),
  ('LCID', 'Lucid Motors fabrique des automobiles électriques. L''entreprise, basée en Californie, a commencé la production de son premier modèle, la Lucid Air, en 2021.', 'Lucid Motors manufactures electric vehicles. The California-based company started production of its first model, the Lucid Air, in 2021.'),
  ('LDOS', 'Leidos fournit des services scientifiques, d''ingénierie, d''intégration de systèmes et d''assistance technique aux agences gouvernementales américaines, notamment le ministère de la Défense, le ministère de la Sécurité intérieure et les services de renseignement, ainsi qu''à des clients commerciaux. Issue de la fusion en 2016 entre Science Applications International Corporation (SAIC) et la division informatique de Lockheed Martin (Information Systems & Global Solutions), l''entreprise est basée en Virginie.', 'Leidos provides scientific, engineering, systems integration, and technical services to U.S. government agencies including the Department of Defense, the Department of Homeland Security, and the Intelligence Community, as well as to select commercial clients. Created through the merger of SAIC and Lockheed Martin''s IT division in 2016, the company is headquartered in Reston, Virginia.'),
  ('LHX', 'L3Harris est un équipementier américain fondé en 2019 par la fusion de L3 Technologies et Harris Corporation. Elle fabrique et vend des systèmes de défense et de communications (radios tactiques, équipements de vision nocturne, systèmes de surveillance) destinés aux gouvernements, aux militaires et au secteur commercial, et figure parmi les six plus grands contractants de défense aux États-Unis.', 'L3Harris is an American equipment manufacturer founded in 2019 from the merger of L3 Technologies and Harris Corporation. It produces and sells defense and communications systems (tactical radios, night vision equipment, surveillance systems) for governments, the military, and the commercial sector, and ranks among the six largest defense contractors in the United States.'),
  ('MAU', 'Maurel & Prom extrait et vend du pétrole et du gaz naturel, principalement au Gabon et en Tanzanie. Depuis août 2016, elle est la filiale du groupe pétrolier public indonésien Pertamina.', 'Maurel & Prom extracts and sells oil and natural gas, mainly in Gabon and Tanzania. Since August 2016, it is a subsidiary of Pertamina, the Indonesian state-owned oil company.'),
  ('MBG', 'Mercedes-Benz Group fabrique et vend des voitures de tourisme et des fourgonnettes sous les marques Mercedes-Benz, Mercedes-AMG et Mercedes-Maybach. Le groupe est le septième plus grand constructeur automobile mondial en chiffre d''affaires selon les données de 2023.', 'Mercedes-Benz Group manufactures and sells passenger cars and vans under the Mercedes-Benz, Mercedes-AMG and Mercedes-Maybach brands. The group is the seventh-largest car manufacturer worldwide by revenue according to 2023 data.'),
  ('MCO', 'Moody''s Corporation produit des évaluations de crédit pour les obligations et les actions, et vend des logiciels d''analyse financière. L''entreprise opère à travers deux divisions : Moody''s Ratings, une agence de notation de crédit, et Moody''s Analytics, un fournisseur de logiciels et services d''analyse financière.', 'Moody''s Corporation produces credit ratings for bonds and stocks, and sells financial analysis software. The company operates through two divisions: Moody''s Ratings, a credit rating agency, and Moody''s Analytics, a provider of financial analysis software and services.'),
  ('METSO', 'Metso fournit des technologies et des services aux secteurs de l''exploitation minière, des granulats, du recyclage et du raffinage des métaux. L''entreprise finlandaise a été créée en 2020 par la fusion de Outotec et Metso Minerals.', 'Metso supplies technology and services to the mining, aggregates, recycling, and metal refining industries. The Finnish company was established in 2020 following the merger of Outotec and Metso Minerals.'),
  ('MFC', 'Manulife Financial Corporation est une compagnie d''assurance et de services financiers canadienne. Elle gère environ 1,4 trillion de dollars canadiens en actifs et opère au Canada, en Asie et aux États-Unis, où elle opère principalement sous la marque John Hancock Financial.', 'Manulife Financial Corporation is a Canadian insurance company and financial services provider. It manages approximately CA$1.4 trillion in assets and operates in Canada, Asia, and the United States, where it primarily operates through its John Hancock Financial division.'),
  ('MMM', '3M fabrique plus de 60 000 produits destinés aux entreprises et aux consommateurs : adhésifs, équipements de protection, films, matériaux isolants, ainsi que des marques connues comme le Scotch et les Post-it. En 2021, l''entreprise a réalisé 35,4 milliards de dollars de chiffre d''affaires avec environ 95 000 salariés dans plus de 70 pays.', '3M manufactures over 60,000 products for businesses and consumers: adhesives, safety equipment, films, insulating materials, and well-known brands such as Scotch tape and Post-it notes. In 2021, the company generated 35.4 billion dollars in revenue with approximately 95,000 employees operating in more than 70 countries.'),
  ('MNST', 'Monster Beverage fabrique des boissons énergisantes vendues dans le monde entier. En 2020, l''entreprise détenait 39 % du marché mondial des boissons énergisantes, estimé à 86 milliards de dollars.', 'Monster Beverage manufactures energy drinks sold worldwide. In 2020, the company held 39% of the global energy drink market, valued at $86 billion.'),
  ('NIO', 'NIO est un constructeur automobile chinois fondé en 2014. L''entreprise se spécialise dans le développement et la production de véhicules électriques.', 'NIO is a Chinese car manufacturer founded in 2014. The company specializes in the development and production of electric vehicles.'),
  ('NN', 'NN Group est une société néerlandaise qui propose des assurances et des services de gestion d''actifs. Elle opère notamment à travers sa filiale Nationale-Nederlanden, l''une des plus grandes compagnies d''assurances et de gestion d''actifs des Pays-Bas.', 'NN Group is a Dutch company that provides insurance and asset management services. It operates notably through its subsidiary Nationale-Nederlanden, one of the largest insurance and asset management companies in the Netherlands.'),
  ('NXI', 'Nexity est une société française de promotion immobilière créée en 2000. Elle conçoit et vend des programmes immobiliers, essentiellement en France.', 'Nexity is a French real estate development company founded in 2000. It designs and sells real estate projects, mainly in France.'),
  ('ON', 'ON Semiconductor fabrique et vend des composants électroniques (puces de gestion de l''énergie et des signaux, circuits logiques, dispositifs discrets) destinés aux secteurs automobile, des télécommunications, de l''informatique, de la consommation, de l''industrie, de l''éclairage LED, médical et militaire. L''entreprise exploite des usines, des bureaux commerciaux et des centres de conception en Amérique du Nord, en Europe et en Asie-Pacifique.', 'ON Semiconductor manufactures and sells semiconductor components including power and signal management chips, logic circuits, and discrete devices for the automotive, communications, computing, consumer, industrial, LED lighting, medical, and military/aerospace sectors. The company operates manufacturing facilities, sales offices, and design centers across North America, Europe, and the Asia Pacific region.'),
  ('PBR', 'Petrobras recherche, extrait, raffine, transporte et vend du pétrole. L''entreprise, détenue à 50,2 % par l''État brésilien en 2020, figure parmi les plus grandes compagnies pétrolières mondiales.', 'Petrobras explores, extracts, refines, transports and sells petroleum. The company, 50.2% owned by the Brazilian state in 2020, ranks among the world''s largest oil companies.'),
  ('PRU', 'Prudential Financial vend des assurances, des produits de retraite et de gestion d''investissements à des clients particuliers et professionnels aux États-Unis et dans plus de 40 pays. En 2019, elle gérait 815,1 milliards de dollars d''actifs et était le plus grand assureur américain.', 'Prudential Financial sells insurance, retirement planning products, and investment management services to retail and institutional customers in the United States and in over 40 countries. In 2019, it managed $815.1 billion in total assets and was the largest insurance provider in the United States.'),
  ('REG', 'Regency Centers possède et exploite des centres commerciaux aux États-Unis, principalement des galeries ancrées par des supermarchés. Au 21 octobre 2020, la société contrôlait 415 propriétés représentant 56 millions de mètres carrés.', 'Regency Centers owns and operates shopping centers in the United States, primarily malls anchored by grocery stores. As of October 21, 2020, the company controlled 415 properties representing 56 million square feet.'),
  ('RKT', 'Reckitt est une entreprise britannique qui fabrique et vend des produits d''hygiène et de santé. Ses marques incluent Dettol (antiseptique), Nurofen (douleur), Strepsils (mal de gorge), Harpic (nettoyant), Veet (épilation), Durex, Lysol, Finish et Vanish.', 'Reckitt is a British company that manufactures and sells health and hygiene products. Its brands include Dettol (antiseptic), Nurofen (pain relief), Strepsils (sore throat), Harpic (toilet cleaner), Veet (hair removal), Durex, Lysol, Finish and Vanish.'),
  ('ROCK-B', 'Rockwool fabrique des produits d''isolation en laine minérale. L''entreprise danoise vend ses produits principalement en Europe.', 'Rockwool manufactures mineral wool insulation products. The Danish company sells its products mainly in Europe.'),
  ('RR', 'Rolls-Royce conçoit, fabrique et distribue des moteurs d''avion et des systèmes de propulsion pour l''aviation, la marine et l''énergie. Le groupe est le quatrième motoriste pour l''aviation commerciale avec 12 % de part de marché en 2020.', 'Rolls-Royce designs, manufactures and distributes aircraft engines and propulsion systems for aviation, marine and energy industries. The group is the world''s fourth largest commercial aircraft engine manufacturer with a 12% market share as of 2020.'),
  ('RTO', 'Rentokil Initial est une société britannique fondée en 1925 qui fournit des services de lutte antiparasitaire et de gestion des installations. Elle opère à l''échelle internationale et est cotée à la Bourse de Londres, où elle figure dans l''indice FTSE 100.', 'Rentokil Initial is a British company founded in 1925 that provides pest control and facilities management services. It operates internationally and is listed on the London Stock Exchange, where it is a constituent of the FTSE 100 Index.'),
  ('RWE', 'RWE produit et commercialise de l''électricité en Europe, en Asie-Pacifique et aux États-Unis. Depuis 2020, l''entreprise se concentre sur la production d''électricité et les énergies renouvelables.', 'RWE generates and trades electricity across Europe, the Asia-Pacific region, and the United States. Since 2020, the company focuses on power generation and renewable energy.'),
  ('SE', 'Sea Limited est une société singapourienne fondée en 2009 qui exploite Garena, un éditeur de jeux vidéo en ligne, et Shopee, une plateforme de commerce électronique opérant en Asie du Sud-Est. Elle est cotée à la Bourse de New-York depuis 2017.', 'Sea Limited is a Singapore-based company founded in 2009 that operates Garena, an online video game publisher, and Shopee, an e-commerce platform operating in Southeast Asia. It has been listed on the New York Stock Exchange since 2017.'),
  ('SK', 'SEB fabrique et vend du petit équipement domestique dans plus de 60 pays. En 2019, le groupe génère un chiffre d''affaires de 7,354 milliards d''euros et emploie près de 34 263 personnes.', 'SEB manufactures and sells small domestic appliances in more than 60 countries. In 2019, the group generated revenue of 7.354 billion euros and employed nearly 34,263 people.'),
  ('SNOW', 'Snowflake propose des services d''hébergement de données dans le cloud. La société a levé plus de 1,4 milliard de dollars en capital-développement avant son introduction en bourse en septembre 2020.', 'Snowflake provides cloud data hosting services. The company raised over 1.4 billion dollars in venture capital before going public in September 2020.'),
  ('SU.TO', 'Suncor Energy est une entreprise canadienne fondée en 1979 qui produit du pétrole brut synthétique à partir des sables bitumineux. Elle commercialise aussi de l''essence et du carburant diesel par un réseau de stations-service.', 'Suncor Energy is a Canadian company founded in 1979 that produces synthetic crude oil from oil sands. It also sells gasoline and diesel fuel through a network of retail stations.'),
  ('SWK', 'Stanley Black & Decker fabrique et vend des outils industriels, du matériel de quincaillerie et des produits de sécurité. L''entreprise est née de la fusion en 2010 entre The Stanley Works et Black & Decker.', 'Stanley Black & Decker manufactures and sells industrial tools, household hardware, and security products. The company was created through the merger of The Stanley Works and Black & Decker in 2010.'),
  ('SY1', 'Symrise est une entreprise chimique allemande qui produit des ingrédients pour cosmétiques, des arômes et des parfums. Elle figure parmi les quatre premiers producteurs mondiaux d''arômes et de parfums pour l''alimentation.', 'Symrise is a German chemicals company that manufactures cosmetic ingredients, flavours and fragrances. It ranks among the top four producers of food flavours and fragrances globally.'),
  ('TDY', 'Teledyne Technologies est un conglomérat industriel américain fondé en 1960. L''extrait ne précise pas ses activités actuelles ni son chiffre d''affaires.', 'Teledyne Technologies is an American industrial conglomerate founded in 1960. The excerpt does not specify its current activities or revenue.'),
  ('TECK-B', 'Teck Resources Limited extrait et traite des minerais et des combustibles fossiles : charbon pour la sidérurgie, cuivre, zinc, et pétrole des sables bitumineux. L''entreprise produit aussi des métaux secondaires comme le plomb, l''argent, l''or et le molybdène.', 'Teck Resources Limited mines and processes minerals and fossil fuels: coal for steelmaking, copper, zinc, and oil sands petroleum. The company also produces secondary metals including lead, silver, gold, and molybdenum.'),
  ('TEVA', 'Teva est une entreprise pharmaceutique israélienne qui fabrique et vend des médicaments génériques et des composants actifs. Elle emploie 46 000 personnes dans le monde.', 'Teva is an Israeli pharmaceutical company that manufactures and sells generic medicines and active pharmaceutical ingredients. It employs 46,000 people worldwide.'),
  ('TM', 'Toyota est un constructeur automobile japonais. En septembre 2023, Toyota est le premier constructeur automobile de l''histoire à avoir produit plus de 300 millions de véhicules.', 'Toyota is a Japanese automobile manufacturer. In September 2023, Toyota became the first automobile manufacturer in history to produce more than 300 million vehicles.'),
  ('TRI.TO', 'Thomson Reuters est un conglomérat technologique canadien créé en 2008 par le rachat de la société britannique Reuters Group. L''entreprise produit du contenu et des technologies destinés aux professionnels.', 'Thomson Reuters is a Canadian technology conglomerate created in 2008 through the acquisition of British company Reuters Group. The company produces content and technologies for professional users.'),
  ('TT', 'Trane Technologies fabrique et vend des systèmes de chauffage, de ventilation, de climatisation et de réfrigération. L''entreprise existe depuis plus de 150 ans et a pris sa forme actuelle en 2020 après le spin-off de sa division outils.', 'Trane Technologies manufactures and sells heating, ventilation, air conditioning, and refrigeration systems. The company has been operating for over 150 years and took its current form in 2020 following the spin-off of its tools division.'),
  ('VTRS', 'Viatris est une entreprise pharmaceutique américaine qui fabrique et vend des médicaments. Née en 2020 de la fusion entre Mylan et la division Upjohn de Pfizer, elle figure parmi les 300 plus grandes entreprises américaines.', 'Viatris is an American pharmaceutical corporation that manufactures and sells medicines. Created in 2020 through the merger of Mylan and Pfizer''s Upjohn division, it ranks among the 300 largest American companies.'),
  ('WIT', 'Wipro fournit des services de conseil informatique et d''intégration de systèmes à plus de 900 grandes entreprises dans le monde. L''entreprise, basée à Bangalore en Inde, emploie 158 200 personnes et opère dans 67 pays.', 'Wipro provides information technology consulting and systems integration services to more than 900 large companies worldwide. The company, based in Bangalore, India, employs 158,200 people and operates in 67 countries.'),
  ('WPM', 'Wheaton Precious Metals achète l''argent et l''or produits par d''autres entreprises minières comme sous-produits de leurs opérations. En 2016, l''entreprise a vendu plus de 29 millions d''onces d''argent et généré un chiffre d''affaires d''exploitation de 584 millions de dollars américains.', 'Wheaton Precious Metals purchases silver and gold produced by other mining companies as by-products of their main operations. In 2016, the company sold over 29 million ounces of silver and generated operating cash flows of 584 million US dollars.'),
  ('ZM', 'Zoom développe une plateforme de visioconférence qui combine vidéo, réunions en ligne, messagerie et outils collaboratifs. L''entreprise vend ses services aux organisations et aux particuliers qui ont besoin de communiquer à distance.', 'Zoom develops a videoconferencing platform that combines video, online meetings, instant messaging and collaborative tools. The company sells its services to organizations and individuals who need to communicate remotely.')
) as v(symbol, fr, en)
where s.symbol = v.symbol;
